import{_ as p,a0 as o,w as r,s as d,I as s,x as e,a1 as i,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何安裝和使用 GNOME Boxes 來創建虛擬機 | LCTT x X-CMD","titleTemplate":false,"description":"如何安裝和使用 GNOME Boxes 來創建虛擬機 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何安裝和使用 GNOME Boxes 來創建虛擬機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何安裝和使用 GNOME Boxes 來創建虛擬機 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20220922 How to Install and Use GNOME Boxes to Create Virtual Machines","title":"如何安裝和使用 GNOME Boxes 來創建虛擬機","tag":"202306","desc":""},"relativePath":"202306/20220922 How to Install and Use GNOME Boxes to Create Virtual Machines.md","filePath":"[post].md"}'),u={name:"202306/20220922 How to Install and Use GNOME Boxes to Create Virtual Machines.md"};function g(h,t,b,m,k,x){const a=o("Link");return r(),d("div",null,[t[26]||(t[26]=s("h1",{id:"如何安裝和使用-gnome-boxes-來創建虛擬機",tabindex:"-1"},[e("如何安裝和使用 GNOME Boxes 來創建虛擬機 "),s("a",{class:"header-anchor",href:"#如何安裝和使用-gnome-boxes-來創建虛擬機","aria-label":"Permalink to “如何安裝和使用 GNOME Boxes 來創建虛擬機”"},"​")],-1)),t[27]||(t[27]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/28/151813xrp87wpccdclwc3c.jpg",alt:""})],-1)),t[28]||(t[28]=s("blockquote",null,[s("p",null,"本快速教程解釋了安裝和使用 GNOME Boxes 以及創建虛擬機的步驟，以及一些提示和故障排除。")],-1)),t[29]||(t[29]=s("p",null,"虛擬化是使用抽象硬件層運行虛擬實例（而不是實際實例）的過程。通俗地説，它允許你同時安裝和運行多個操作系統（Linux、Windows）。",-1)),s("p",null,[i(a,{href:"https://www.redhat.com/en/topics/virtualization/what-is-a-virtual-machine"},{default:l(()=>[...t[0]||(t[0]=[e("虛擬機",-1)])]),_:1}),t[1]||(t[1]=e(" 是一個模擬操作系統，它運行在另一個操作系統之上，並使用與主機相同的硬件和存儲空間。雖然，你可以控制可以分配給虛擬機的共享內存或空間量。",-1))]),s("p",null,[t[3]||(t[3]=e("有多種軟件可用於創建虛擬機，例如 ",-1)),i(a,{href:"https://www.debugpoint.com/tag/virtualbox/"},{default:l(()=>[...t[2]||(t[2]=[e("Virtual Box",-1)])]),_:1}),t[4]||(t[4]=e("、KVM、Hyper-V、VMWare player 和 GNOME Boxes。",-1))]),s("p",null,[t[6]||(t[6]=e("但老實説，它們中的大多數使用起來都很複雜，有時還不夠穩定。",-1)),i(a,{href:"https://wiki.gnome.org/Apps/Boxes"},{default:l(()=>[...t[5]||(t[5]=[e("GNOME Boxes",-1)])]),_:1}),t[7]||(t[7]=e(" 是另一個自由開源的軟件，它非常易於使用，通過抽象出大量選項讓你可以輕鬆創建和管理虛擬機。",-1))]),t[30]||(t[30]=n('<h3 id="安裝-gnome-boxes" tabindex="-1">安裝 GNOME Boxes <a class="header-anchor" href="#安裝-gnome-boxes" aria-label="Permalink to “安裝 GNOME Boxes”">​</a></h3><p>如果你正在運行 Fedora 的 GNOME 定製版，你應該已經安裝了它。但是，對於 Ubuntu、Linux Mint、Kubuntu 和其他發行版，你只需運行以下命令即可將其安裝到你的系統中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-boxes</span></span></code></pre></div><h4 id="通過-flatpak" tabindex="-1">通過 Flatpak <a class="header-anchor" href="#通過-flatpak" aria-label="Permalink to “通過 Flatpak”">​</a></h4>',4)),s("p",null,[t[9]||(t[9]=e("它也可以通過 Flatpak 包獲得。我會推薦你使用這個版本。首先，使用 ",-1)),i(a,{href:"https://www.debugpoint.com/how-to-install-flatpak-apps-ubuntu-linux/"},{default:l(()=>[...t[8]||(t[8]=[e("本指南",-1)])]),_:1}),t[10]||(t[10]=e(" 在系統中安裝 Flatpak，然後從終端運行以下命令進行安裝。",-1))]),t[31]||(t[31]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub org.gnome.Boxes</span></span></code></pre></div><h3 id="使用-gnome-boxes-創建虛擬機" tabindex="-1">使用 GNOME Boxes 創建虛擬機 <a class="header-anchor" href="#使用-gnome-boxes-創建虛擬機" aria-label="Permalink to “使用 GNOME Boxes 創建虛擬機”">​</a></h3><p>從應用菜單啓動 GNOME Boxes。</p><p>要創建虛擬機，你需要要虛擬化的操作系統的鏡像（*.ISO）。</p><p>你可以從發行版的官方下載頁面下載任何操作系統 ISO 鏡像。對於本指南，我使用的是 Pop!_OS，這是一個優秀的 Linux 發行版。</p><p>啓動後，單擊頂部的 “+” 圖標啓動並選擇“<ruby>創建虛擬機<rt>Create a virtual machine</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Create-Virtual-Machine.png" alt="Create Virtual Machine"></p><p>在下一個窗口中，你可以選擇已經可用的下載，或者你可以選擇你的 ISO 文件作為操作系統源。單擊“<ruby>操作系統鏡像文件<rt>Operating system image file</rt></ruby>”並選擇你的 ISO 文件。</p><p>分配虛擬機的內存和存儲空間。請記住，你的虛擬機將從主機系統獲取內存和存儲空間。所以儘量不要分配為最大值。</p><p>例如，在下圖中，我從主機系統的 8GB 總內存中為虛擬機（客户機）分配了 2GB 內存。</p><p>同樣，如果你只是想測試操作系統，也請選擇最小存儲空間。但是，如果你正在為服務器或嚴肅的工作創建虛擬機，請合理分配你要分配的空間或內存量。</p><p>另一件需要記住的重要事情是，除非你刪除虛擬機，否則你允許的存儲磁盤空間將被永久佔用。因此，即使你的虛擬機沒有使用整個分配的空間，你也不會獲得那麼多的可用磁盤空間。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Allocate-resources-for-your-virtual-machine.png" alt="Allocate resources for your virtual machine"></p><p>繼續安裝。</p><p>在分區窗口中，你應該看到一個硬盤和一個分區，這就是虛擬機的磁盤空間。通常，它們被命名為 <code>/dev/vda</code> 或者 <code>/dev/sda</code>。</p><p>不用擔心；你可以隨意使用此分區，這不會影響你的物理磁盤分區或實際主機系統上的任何數據。安裝 Linux 時遵循相同的 <code>/root</code> 分區，然後繼續。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Virtual-machine-partition.png" alt="Virtual machine partition"></p><p>完成安裝後，你應該會在虛擬機中看到新的操作系統。在 GNOME Boxes 中，你應該會看到一個系統條目。你可以單擊它啓動虛擬機。</p><p>你可以使用虛擬機操作系統的內部關閉選項關閉虛擬機。</p><p>如果需要，你還可以通過選擇上下文菜單選項來刪除虛擬機。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/Context-menu-in-installed-virtual-machine.png" alt="Context menu in installed virtual machine"></p><p>你還可以從屬性窗口檢查你的虛擬機使用了多少內存和 CPU。</p><p>請注意，你可以使用屬性調整現有虛擬機的內存和其他項目。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/05/System-properties.png" alt="System properties"></p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><p>以下是你在使用 GNOME Boxes 時可能遇到的一些常見錯誤或問題。</p><h4 id="_1、虛擬機中的分辨率問題" tabindex="-1">1、虛擬機中的分辨率問題 <a class="header-anchor" href="#_1、虛擬機中的分辨率問題" aria-label="Permalink to “1、虛擬機中的分辨率問題”">​</a></h4><p>如果你的虛擬機分辨率很低，這與你的主機系統不兼容，那麼你必須安裝以下項目。在客户系統（而不是主機系統）中打開終端並運行以下命令。</p><p>對於基於 Ubuntu 的發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install spice-vdagent spice-webdavd</span></span></code></pre></div><p>對於 Fedora 系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install spice-vdagent spice-webdavd</span></span></code></pre></div><p>這兩個包有助於確定合適的分辨率、在主機和客户之間複製/粘貼、通過公共文件夾共享文件等。</p><p>安裝後，重新啓動客户系統；或者你可以在重啓後註銷並重新登錄一次，你應該會看到正確的分辨率。</p><h4 id="_2、在-ubuntu-18-04-中-gnome-boxes-不能啓動虛擬機" tabindex="-1">2、在 Ubuntu 18.04 中 GNOME Boxes 不能啓動虛擬機 <a class="header-anchor" href="#_2、在-ubuntu-18-04-中-gnome-boxes-不能啓動虛擬機" aria-label="Permalink to “2、在 Ubuntu 18.04 中 GNOME Boxes 不能啓動虛擬機”">​</a></h4><p>如果你在 Boxes 3.34 中創建虛擬機，那麼你應該知道有一個錯誤導致你的虛擬機無法啓動。要解決這個問題，你必須執行一些額外的步驟。請記住，最新的 Boxes 3.36 不需要這些。</p><p>打開終端窗口並運行以下命令來更改 qemu 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo gedit /etc/modprobe.d/qemu-system-x86.conf</span></span></code></pre></div><p>在上面的文件中添加以下行並保存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>group=kvm</span></span></code></pre></div><p>現在，運行以下命令將你的用户名添加到 KVM 組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -a -G kvm &lt;你的帳户名稱&gt;</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本文中，你瞭解瞭如何安裝和使用 GNOME Boxes 來利用虛擬化。我希望它能幫助你。</p><p>🗨️ 如果你遇到任何錯誤或對 GNOME Boxes 的虛擬機有任何疑問，請使用下面的評論欄告訴我。</p><p><em>（題圖：MJ/b4d091cf-9585-468b-9ce6-ba0b0c69cce4）</em></p><hr>',47)),s("p",null,[t[12]||(t[12]=e("via: ",-1)),i(a,{href:"https://www.debugpoint.com/install-use-gnome-boxes/"},{default:l(()=>[...t[11]||(t[11]=[e("https://www.debugpoint.com/install-use-gnome-boxes/",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=e("作者：",-1)),i(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...t[13]||(t[13]=[e("Arindam",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),i(a,{href:"https://github.com/lkxed"},{default:l(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:l(()=>[...t[15]||(t[15]=[e("geekpi",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const C=p(u,[["render",g]]);export{c as __pageData,C as default};
